// Pure JS SHA-256 (scratch verification build) - no platform hashing module used.
const K = new Uint32Array(64);
const H0 = new Uint32Array(8);
(function derive(){
  // K[i] = frac(cbrt(prime_i)) * 2^32 ; H0[i] = frac(sqrt(prime_i)) * 2^32
  let n = 2, c = 0, h = 0;
  const isP = (x)=>{ for(let d=2; d*d<=x; d++) if(x%d===0) return false; return true; };
  while (c < 64) {
    if (isP(n)) {
      const cb = Math.cbrt(n);
      K[c] = Math.floor((cb - Math.floor(cb)) * 2**32) >>> 0;
      if (h < 8) { const sq = Math.sqrt(n); H0[h] = Math.floor((sq - Math.floor(sq)) * 2**32) >>> 0; h++; }
      c++;
    }
    n++;
  }
})();

const rotr = (x,n)=>((x>>>n)|(x<<(32-n)))>>>0;

export function sha256(bytes){
  const h = Uint32Array.from(H0);
  const bitLenLo = (bytes.length * 8) >>> 0;
  const bitLenHi = Math.floor((bytes.length * 8) / 2**32) >>> 0;
  const withPad = (((bytes.length + 9) + 63) & ~63);
  const m = new Uint8Array(withPad);
  m.set(bytes); m[bytes.length] = 0x80;
  const dv = new DataView(m.buffer);
  dv.setUint32(withPad - 8, bitLenHi, false);
  dv.setUint32(withPad - 4, bitLenLo, false);
  const W = new Uint32Array(64);
  for (let off = 0; off < withPad; off += 64) {
    for (let i = 0; i < 16; i++) W[i] = dv.getUint32(off + i*4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = (rotr(W[i-15],7) ^ rotr(W[i-15],18) ^ (W[i-15]>>>3))>>>0;
      const s1 = (rotr(W[i-2],17) ^ rotr(W[i-2],19) ^ (W[i-2]>>>10))>>>0;
      W[i] = (W[i-16] + s0 + W[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,hh] = h;
    for (let i = 0; i < 64; i++) {
      const S1 = (rotr(e,6) ^ rotr(e,11) ^ rotr(e,25))>>>0;
      const ch = ((e & f) ^ (~e & g))>>>0;
      const t1 = (hh + S1 + ch + K[i] + W[i])>>>0;
      const S0 = (rotr(a,2) ^ rotr(a,13) ^ rotr(a,22))>>>0;
      const maj = ((a & b) ^ (a & c) ^ (b & c))>>>0;
      const t2 = (S0 + maj)>>>0;
      hh=g; g=f; f=e; e=(d+t1)>>>0; d=c; c=b; b=a; a=(t1+t2)>>>0;
    }
    h[0]=(h[0]+a)>>>0; h[1]=(h[1]+b)>>>0; h[2]=(h[2]+c)>>>0; h[3]=(h[3]+d)>>>0;
    h[4]=(h[4]+e)>>>0; h[5]=(h[5]+f)>>>0; h[6]=(h[6]+g)>>>0; h[7]=(h[7]+hh)>>>0;
  }
  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  for (let i=0;i<8;i++) odv.setUint32(i*4, h[i], false);
  return out;
}

export function hmacSha256(key, msg){
  const B = 64;
  let k = key;
  if (k.length > B) k = sha256(k);
  const kp = new Uint8Array(B); kp.set(k);
  const ip = new Uint8Array(B), op = new Uint8Array(B);
  for (let i=0;i<B;i++){ ip[i] = kp[i] ^ 0x36; op[i] = kp[i] ^ 0x5c; }
  const inner = new Uint8Array(B + msg.length); inner.set(ip); inner.set(msg, B);
  const ih = sha256(inner);
  const outer = new Uint8Array(B + 32); outer.set(op); outer.set(ih, B);
  return sha256(outer);
}

export const hex = (u8)=>Array.from(u8, b=>b.toString(16).padStart(2,'0')).join('');
export const KTAB = K, HTAB = H0;
