import { hmacSha256, hex } from './sha.mjs';
const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
export function b64url(bytes){
  let out=''; let i=0;
  for (; i+3<=bytes.length; i+=3){
    const v=(bytes[i]<<16)|(bytes[i+1]<<8)|bytes[i+2];
    out+=B64[(v>>>18)&63]+B64[(v>>>12)&63]+B64[(v>>>6)&63]+B64[v&63];
  }
  const rem=bytes.length-i;
  if(rem===1){const v=bytes[i]<<16; out+=B64[(v>>>18)&63]+B64[(v>>>12)&63];}
  else if(rem===2){const v=(bytes[i]<<16)|(bytes[i+1]<<8); out+=B64[(v>>>18)&63]+B64[(v>>>12)&63]+B64[(v>>>6)&63];}
  return out;
}
const ESC={0x08:'\\b',0x09:'\\t',0x0a:'\\n',0x0c:'\\f',0x0d:'\\r',0x22:'\\"',0x5c:'\\\\'};
export function pyJsonString(s){
  let out='"';
  for (const ch of s){
    const cp=ch.codePointAt(0);
    if(ESC[cp]!==undefined && cp<0x80){out+=ESC[cp];}
    else if(cp>=0x20 && cp<=0x7e){out+=ch;}
    else if(cp<=0xffff){out+='\\u'+cp.toString(16).padStart(4,'0');}
    else{const v=cp-0x10000; const hi=0xd800+(v>>10), lo=0xdc00+(v&0x3ff);
      out+='\\u'+hi.toString(16).padStart(4,'0')+'\\u'+lo.toString(16).padStart(4,'0');}
  }
  return out+'"';
}
const enc=s=>new TextEncoder().encode(s);
export function makeToken(payload){
  const headerJson='{"alg":"HS256","typ":"JWT"}';
  const payloadJson='{"data":'+pyJsonString(payload)+'}';
  const h=b64url(enc(headerJson));
  const p=b64url(enc(payloadJson));
  const signing=h+'.'+p;
  const sig=b64url(hmacSha256(enc('my_secret_key'), enc(signing)));
  return {token:signing+'.'+sig, signing, signingLen:signing.length, payloadJson, sigHex:hex(hmacSha256(enc('my_secret_key'),enc(signing)))};
}
